{"command": "python - <<'EOF'
from decimal import Decimal
from ledgerly.invoice import add_line
from ledgerly.models import Invoice
from ledgerly.errors import BillingError

inv = Invoice("i", "c")
l = add_line(inv, "Seat", 2, Decimal("5.00"))
print(l, inv.lines == [l])

for q, p in [(0, "1"), (-1, "1"), (1.5, "1"), (True, "1"), (1, "-1"), (1, "abc")]:
    try:
        add_line(Invoice("i","c"), "x", q, p)
        print("NO ERROR", q, p)
    except BillingError as e:
        print("ok", q, p, e.code)

issued = Invoice("i","c", status="issued")
try:
    add_line(issued, "x", 1, "1")
except BillingError as e:
    print("ok issued", e.code)
EOF"}

